import test from 'node:test';
import assert from 'node:assert/strict';
import { createFirstSplitDailyProductionRun } from '../src/intelligence/split-daily-production.js';
import { productionLabels, publishSplitDailyUnit } from '../src/production/split-daily-publish.js';
import { GoogleBloggerApiAdapter } from '../src/services/blogger.js';
class Fake {
    seed;
    posts = new Map();
    insert = 0;
    publish = 0;
    constructor(seed = []) {
        this.seed = seed;
        for (const post of seed)
            this.posts.set(post.postId, post);
    }
    async findMatches(input) { return [...this.posts.values()].filter(post => post.title === input.title && post.labels.includes(input.label)); }
    async insertDraft(input) { this.insert++; const post = { postId: `draft-${this.insert}`, title: input.title, content: input.content.replace(/^.*?<body>/s, '').replace(/<\/body>.*$/s, ''), status: 'DRAFT', url: null, labels: input.labels }; this.posts.set(post.postId, post); return post; }
    async readPost(id) { return this.posts.get(id); }
    async publishDraft(id) { this.publish++; const old = this.posts.get(id); const url = `https://motusnova.blogspot.com/2026/09/${id}.html`; this.posts.set(id, { ...old, status: 'PUBLISHED', url }); return { postId: id, publicPostUrl: url, publishedAt: '2026-10-06T10:00:00+09:00' }; }
    async fetchPublic() { return { status: 200, body: 'ok' }; }
}
const reviewedAt = '2026-10-06T09:00:00+09:00';
test('Sprint 4L creates and publishes one approved split unit exactly once', async () => { const unit = createFirstSplitDailyProductionRun().units.find(item => item.category === 'US_MARKET'); const adapter = new Fake(); const result = await publishSplitDailyUnit({ unit, adapter, reviewedAt, pdfConsistency: 'PASS' }); assert.equal(result.state, 'PUBLISHED'); assert.equal(result.postsInsertCallCount, 1); assert.equal(result.publishApiCallCount, 1); assert.equal(adapter.insert, 1); assert.equal(adapter.publish, 1); assert.equal(result.draftValidation?.svgCount, 4); assert.equal(result.searchTrackingRegistration?.trigger, 'PUBLICATION_PUBLISHED'); assert.equal(result.commerce.enabled, false); });
test('Sprint 4L recovers one remote draft and does not insert a duplicate', async () => { const unit = createFirstSplitDailyProductionRun().units[0]; const label = productionLabels[unit.category]; const seed = { postId: 'existing', title: unit.title, content: unit.render.html, status: 'DRAFT', url: null, labels: [label] }; const adapter = new Fake([seed]); const result = await publishSplitDailyUnit({ unit, adapter, reviewedAt, pdfConsistency: 'PASS' }); assert.equal(result.state, 'PUBLISHED'); assert.equal(result.remoteDuplicateCount, 1); assert.equal(result.postsInsertCallCount, 0); assert.equal(result.publishApiCallCount, 1); });
test('Sprint 4L isolates duplicate conflict and PDF mismatch without external writes', async () => { const unit = createFirstSplitDailyProductionRun().units[2]; const label = productionLabels[unit.category]; const seed = (id) => ({ postId: id, title: unit.title, content: unit.render.html, status: 'DRAFT', url: null, labels: [label] }); const duplicate = new Fake([seed('a'), seed('b')]); const conflict = await publishSplitDailyUnit({ unit, adapter: duplicate, reviewedAt, pdfConsistency: 'PASS' }); assert.equal(conflict.state, 'HOLD'); assert.equal(conflict.remoteDuplicateCount, 2); assert.equal(duplicate.publish, 0); const mismatch = new Fake(); const held = await publishSplitDailyUnit({ unit, adapter: mismatch, reviewedAt, pdfConsistency: 'FAIL' }); assert.equal(held.state, 'HOLD'); assert.equal(mismatch.insert, 0); });
test('Sprint 4L Google adapter looks up draft and live before exact one-shot publish', async () => { const calls = []; const responses = [{ items: [] }, { items: [] }, { id: 'draft-1' }, { id: 'draft-1', title: 'Title', content: '<article style="max-width:100%">Body</article>', status: 'DRAFT', labels: ['Label'] }, { id: 'draft-1', url: 'https://motusnova.blogspot.com/2026/10/post.html', status: 'LIVE', published: '2026-10-06T10:00:00+09:00' }]; const fakeFetch = async (input, init) => { const url = String(input); calls.push({ url, method: init?.method ?? 'GET' }); return new Response(JSON.stringify(responses.shift()), { status: 200, headers: { 'content-type': 'application/json' } }); }; const adapter = new GoogleBloggerApiAdapter(name => name === 'TOKEN' ? 'access' : undefined, fakeFetch); const config = { previewBaseUrl: 'https://preview.local', placeholderBaseUrl: 'https://pending.local', blogId: 'blog', credentialEnvironmentVariable: 'TOKEN', publisher: { brand: 'MOTUS', displayName: 'MOTUS | What Moves the World', baseUrl: 'https://motusnova.blogspot.com/', ctaText: '전체 분석은 MOTUS에서 확인하세요', categories: ['Daily Market'] } }; assert.deepEqual(await adapter.findMatchingPosts({ title: 'Title', label: 'Label' }, config), []); const draft = await adapter.insertDraftContent({ title: 'Title', content: '<html><body><article>Body</article></body></html>', labels: ['Label'] }, config); assert.equal(draft.status, 'DRAFT'); const published = await adapter.publishDraftPost('draft-1', config); assert.equal(published.publicPostUrl, 'https://motusnova.blogspot.com/2026/10/post.html'); assert.equal(calls.filter(call => call.url.endsWith('/publish') && call.method === 'POST').length, 1); assert.equal(calls.filter(call => call.url.includes('/posts?') && call.method === 'GET').length, 2); });
